 "content": "def transform(grid):
    """Zero the two rows and columns marked by a 2x2 zero block,
    preserving cells whose value is 2.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = None
    for r in range(h - 1):
        for c in range(w - 1):
            if (grid[r][c] == 0 and grid[r][c + 1] == 0
                    and grid[r + 1][c] == 0 and grid[r + 1][c + 1] == 0):
                marker = (r, c)
                break
        if marker is not None:
            break
    if marker is None:
        return out
    r, c = marker
    marked_rows = {r, r + 1}
    marked_cols = {c, c + 1}
    for i in range(h):
        for j in range(w):
            if (i in marked_rows or j in marked_cols) and grid[i][j] != 2:
                out[i][j] = 0
    return out

